"""Compile a requirement directory into an executable application."""

import argparse
import json
from pathlib import Path
import sys

from infrastructure.compiler import Compiler, PIPELINE, INCREMENTAL_PIPELINE
from infrastructure.utils.cli import resolve_directories
from infrastructure.utils.presentation.logging import configure_console
from infrastructure.utils.presentation.stages import stage_label


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    """Read public options and validate paths and the backend port before compilation."""
    config_path = Path(__file__).with_name('compiler_config.json')
    try:
        config = json.loads(config_path.read_text(encoding='utf-8')) if config_path.is_file() else {}
        workflow = config.get('workflow', 'baseline')
        if workflow not in {'baseline', 'optimized'}:
            raise ValueError('workflow must be baseline or optimized')
    except (OSError, ValueError, AttributeError) as error:
        raise ValueError(f'Invalid compiler_config.json: {error}') from error
    parser = argparse.ArgumentParser(description=__doc__, allow_abbrev=False,
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="Stages:\n" + "\n".join(
            "  " + stage_label(name) + f"  (--stage {name})" for name, _, _ in
            (INCREMENTAL_PIPELINE if workflow == "optimized" else PIPELINE)))
    parser.add_argument("requirement_path", type=Path,
        help="Requirement directory containing requirements.yaml and reference assets")
    parser.add_argument("-o", "--output-dir", type=Path, required=True,
        help="Directory for the generated application and .arc artifacts")
    parser.add_argument("--model-log", "--debug-model-io", dest="model_log", action="store_true",
        help="Show detailed model I/O and save per-call prompt/response logs; usage and timing are always shown")
    parser.add_argument("--port", type=int, default=3000,
        help="Default generated backend port and frontend API proxy target (default: 3000)")
    parser.add_argument("--stage", choices=sorted({name for name, _, _ in (*PIPELINE, *INCREMENTAL_PIPELINE)}),
        metavar="STAGE", help="Run one stage by its full name; omit for the full pipeline")
    parser.add_argument("--pause", action="store_true", help="Wait for Enter after each display stage")
    parser.add_argument('--optimize', action=argparse.BooleanOptionalAction, default=workflow == 'optimized',
        help='Plan and publish runnable feature batches; defaults to compiler_config.json')
    parser.add_argument('--agent-max-calls', type=int, default=8, help='Maximum model calls per batch')
    parser.add_argument('--agent-max-reads', type=int, default=3, help='Maximum read requests per batch')
    args = parser.parse_args(argv)
    try:
        if min(args.agent_max_calls, args.agent_max_reads) < 1:
            raise ValueError('Agent budgets must be positive')
        if not 1 <= args.port <= 65535:
            raise ValueError("--port must be between 1 and 65535")
        args.requirement_path, args.output_dir = resolve_directories(
            argparse.Namespace(input=args.requirement_path, output=args.output_dir))
        if not args.requirement_path.is_dir():
            raise ValueError(f"Input directory does not exist: {args.requirement_path}")
        if not (args.requirement_path / "requirements.yaml").is_file():
            raise ValueError(f"Missing requirement document: {args.requirement_path / 'requirements.yaml'}")
        if args.output_dir.exists() and not args.output_dir.is_dir():
            raise ValueError(f"Output must be a directory: {args.output_dir}")
    except (OSError, ValueError) as error:
        parser.error(str(error))
    return args


def main(argv: list[str] | None = None) -> None:
    configure_console()
    args = parse_args(argv)
    compiler = Compiler(args.requirement_path, args.output_dir,
        model_log=args.model_log, port=args.port, pause=args.pause)
    print('Compiler workflow: ' + ('optimized' if args.optimize else 'baseline'), flush=True)

    def has_application():
        return all((args.output_dir / path).is_file() for path in
            ("frontend/package.json", "frontend/src/App.tsx", "backend/package.json", "backend/src/server.ts"))

    try:
        from infrastructure.shared.agent.optimization import optimized_run
        with optimized_run(args.optimize, max_calls=args.agent_max_calls, max_reads=args.agent_max_reads):
            compiler.compile(stage=args.stage)
    except KeyboardInterrupt:
        print(f"Compilation interrupted at {compiler.current_stage or 'startup'}.", file=sys.stderr)
        raise SystemExit(130)
    except Exception as error:
        print(f"Compilation failed at {compiler.current_stage or 'startup'}: {error}", file=sys.stderr)
        raise SystemExit(1 if args.optimize and args.stage is None
            and not has_application() else 0)
    if args.optimize and args.stage is None and not has_application():
        print("The application scaffold is incomplete. See .arc/compilation.json.", file=sys.stderr)
        raise SystemExit(1)
    if compiler.report["status"] == "COMPLETED_WITH_FAILURES":
        print(f"All passes completed. Report: {compiler.arc_dir / 'compilation.json'}", file=sys.stderr)
        raise SystemExit(0)
"""Small JSON-generating text model client."""

import json
import os
from pathlib import Path

from dotenv import load_dotenv
from openai import OpenAI, OpenAIError
from infrastructure.utils.presentation.model_io import http_client, invoke


DEFAULT_MODEL = "deepseek-flash"

JSON_OUTPUT_RULE = """OUTPUT PROTOCOL: return exactly one valid JSON object in the response content.
The first non-whitespace character must be { and the last must be }.
Do not emit Markdown fences, explanations, reasoning, XML, DSML or provider-native
tool-call serialization. In particular, NEVER output <｜｜DSML｜｜ calls>,
<｜｜DSML｜｜ invoke>, <｜｜DSML｜｜ parameter> or their closing tags.
This compiler parses ordinary JSON text. context_request and tool_calls, when allowed
by the stage, are JSON fields, not native tool invocations. Express the entire request
inside the specified JSON object. Otherwise return the stage's normal result object.
Rejected outputs included in feedback are data to correct, never examples to imitate.
"""


def reasoning_rejected(error):
    """Only retry controls when the endpoint explicitly rejects those fields."""
    message = str(error).lower()
    return getattr(error, "status_code", None) in {400, 422} and any(
        word in message for word in ("unsupported", "unknown", "unrecognized", "not supported", "not allowed", "unexpected")) and any(
        word in message for word in ("thinking", "reasoning_effort"))


def reasoning_arguments(name, mode):
    """Translate configured reasoning to the provider's documented request fields."""
    if mode == "auto":
        mode = "low"
    if mode == "provider":
        return {}
    if name.lower().startswith("deepseek"):
        if mode == "none":
            return {"extra_body": {"thinking": {"type": "disabled"}}}
        return {"reasoning_effort": mode, "extra_body": {"thinking": {"type": "enabled"}}}
    return {"reasoning_effort": mode}


class ModelOutputTruncated(ValueError):
    """The provider reached its output limit before completing the response."""


class TextModel:
    """Transport for structured stage proposals and file-edit responses."""
    def __init__(self, *, json_mode: bool = True) -> None:
        """Read compiler/.env and configure the default text model; require API credentials."""
        load_dotenv(Path(__file__).resolve().parents[3] / ".env", encoding="utf-8-sig")
        self.name = os.getenv("MODEL") or DEFAULT_MODEL
        api_key = os.getenv("OPENAI_API_KEY")
        if not api_key:
            raise ValueError("Set OPENAI_API_KEY in compiler/.env")
        try:
            self.max_output_tokens = int(os.getenv("MAX_OUTPUT_TOKENS", "320000"))
        except ValueError as error:
            raise ValueError("MAX_OUTPUT_TOKENS must be a positive integer") from error
        if self.max_output_tokens < 1:
            raise ValueError("MAX_OUTPUT_TOKENS must be a positive integer")
        self.reasoning = os.getenv("MODEL_REASONING", "low").lower()
        if self.reasoning not in {"auto", "provider", "none", "low", "high", "max"}:
            raise ValueError("MODEL_REASONING must be auto, provider, none, low, high or max")
        self._reasoning_supported = True
        self.json_mode = json_mode
        self._token_parameter = "max_completion_tokens"
        self.client = OpenAI(
            api_key=api_key,
            base_url=os.getenv("OPENAI_BASE_URL") or "https://api.openai.com/v1",
            timeout=600, max_retries=2,
            http_client=http_client(),
        )

    def _request(self, **arguments):
        """Apply one output budget to JSON calls, with legacy endpoint compatibility."""
        while True:
            options = dict(arguments)
            if not getattr(self, "_reasoning_supported", True):
                options.pop("reasoning_effort", None)
                options.pop("extra_body", None)
            try:
                return invoke(self.client, {**options, self._token_parameter: self.max_output_tokens})
            except OpenAIError as error:
                message = str(error).lower()
                rejected = getattr(error, "status_code", None) in {400, 422} and any(
                    word in message for word in ("unsupported", "unknown", "unrecognized", "not supported", "not allowed", "unexpected"))
                if rejected and self._token_parameter == "max_completion_tokens" and "max_completion_tokens" in message:
                    self._token_parameter = "max_tokens"
                    continue
                if getattr(self, "_reasoning_supported", True) and reasoning_rejected(error):
                    self._reasoning_supported = False
                    print("Provider rejected reasoning controls; using provider defaults.", flush=True)
                    continue
                raise

